CREATE UNIQUE INDEX IF NOT EXISTS idx_ed_platform_entity
  ON public.extraction_definitions(entity_type) WHERE scope = 'platform' AND org_id IS NULL;
INSERT INTO public.extraction_definitions
  (entity_type, scope, org_id, coach_id, canonical_definition, anti_patterns, grammar, good_examples, bad_examples, active)
VALUES
('pain_point', 'platform', NULL, NULL, 'A problem the prospect currently EXPERIENCES, stated by a prospect-side speaker, in their business operations or finance function. Must be present-tense reality, not risk, desire, or hypothesis.', '["NOT pains: desires (''we want dashboards'' -> ideal/desired), risks not yet experienced (''we might outgrow it''), rep assertions, research-derived industry pains never voiced by the prospect, and restatements of an existing pain (dedup: enrich the existing row)."]'::jsonb, '{"row_rules": "One row per distinct underlying problem. Quantification (annual_cost / annual_hours) only from explicit prospect statements or simple arithmetic on stated numbers (2 days/week x 50 weeks), with the conversion noted. category from the controlled list; affected_team and mentioned_by captured when stated.", "signals": "what kills us; we waste; takes forever; error-prone; we can''t; manual; my team spends"}'::jsonb, '["Quote: ''My controller spends two days a week keying AP'' -> pain: manual AP entry", "annual_hours ~800 (2d x 8h x 50wk, conversion noted)", "affected_team: accounting."]'::jsonb, '["Quote: ''Companies like ours usually struggle with consolidation'' (rep) -> nothing", "rep speech."]'::jsonb, true),
('business_catalyst', 'platform', NULL, NULL, 'A force or event actively DRIVING change: something happening (or recently happened) that creates the need to act. Acquisition, growth, new leadership, system end-of-life, funding event, regulatory change, audit finding.', '["NOT catalysts: pains (current suffering without a driving force), compelling events (consequences of inaction), generic ambitions (''we want to grow''), or the rep''s narrative of why they should buy."]'::jsonb, '{"row_rules": "One row per distinct force. category + urgency from stated timeline pressure; impact from stated consequences. Research-sourced catalysts allowed ONLY with citation (e.g., press release of an acquisition) and remain unverified until voiced on a call.", "signals": "we just acquired; growing fast; new CFO; our PE firm wants; the system sunsets; we raised"}'::jsonb, '["Quote: ''We closed two acquisitions this year and the board wants consolidated numbers by Q3'' -> catalysts: acquisition activity", "board reporting mandate (urgency: Q3)."]'::jsonb, '["Quote: ''Close is painful'' -> pain, not catalyst."]'::jsonb, true),
('compelling_event', 'platform', NULL, NULL, 'The bad thing that happens if the prospect does NOT change: the consequence of inaction, with a date or trigger where stated. The Sage canon definition; the inverse of a catalyst.', '["NOT CEs: catalysts (drivers), soft preferences (''we''d like it before busy season'' is timing color unless a consequence is attached), vendor-created urgency (rep''s discount deadline is not the prospect''s CE)."]'::jsonb, '{"row_rules": "One row per consequence. event_date when a date/trigger is stated; strength from the stated severity and specificity; verified=true only when prospect-voiced (research can propose CE candidates only as hypotheses, never as CE rows).", "signals": "if we don''t; by [date] we have to; the bank requires; we lose the contract unless; can''t survive another year-end like"}'::jsonb, '["Quote: ''If we can''t produce audited consolidations by June the credit line doesn''t renew'' -> CE: credit-line non-renewal", "date: June", "strength: high."]'::jsonb, '["Quote: ''Pricing goes up next quarter'' (rep) -> vendor urgency", "never a CE."]'::jsonb, true),
('decision_criterion', 'platform', NULL, NULL, 'A standard the prospect states they will judge vendors against: must-haves, evaluation factors, comparison dimensions.', '["NOT criteria: ideal-solution color without pass/fail weight, the rep''s differentiators recited back, process steps (''we''ll do demos'' is decision_process)."]'::jsonb, '{"row_rules": "One row per criterion; importance from stated weight (''non-negotiable'' vs ''nice to have''); our_position filled only from evidence, else Unknown.", "signals": "has to have; must; we''re comparing on; what matters to us is; deal-breaker"}'::jsonb, '["Quote: ''Multi-entity consolidation is non-negotiable, and it has to talk to ServiceTitan'' -> two criteria, both must-have."]'::jsonb, '["Quote: ''Your dimensions thing seems cool'' -> reaction, not a stated criterion", "partial at most."]'::jsonb, true),
('company_system', 'platform', NULL, NULL, 'A software system the company currently uses (is_current) or states it needs (is_needed), with category, and integration purpose when stated.', '["NOT systems: competitors under evaluation (deal_competitors), clients'' systems, generic tool mentions with no business role (Slack small talk)."]'::jsonb, '{"row_rules": "Natural key: system_name + category per deal; match-before-insert (NetSuite vs ''NetSuite ERP'' = same row). confirmed=true only when prospect-voiced; research rows stay confidence-tagged until confirmed.", "signals": "we use; we''re on; runs on; we need it to talk to"}'::jsonb, '["Quote: ''Field ops runs on ServiceTitan'' -> ServiceTitan, category operational, is_current, confirmed."]'::jsonb, '["Quote: ''NetSuite quoted us last month'' -> competitor."]'::jsonb, true),
('deal_risk', 'platform', NULL, NULL, 'A threat to THE DEAL (not to the prospect''s business): competitive bias, no access to power, timeline slippage, budget uncertainty, champion weakness.', '["NOT risks: the prospect''s business problems (pains), generic deal-stage facts, hypotheses without quote backing (those go to deal_hypotheses)."]'::jsonb, '{"row_rules": "One row per risk; category + severity from evidence; status open by default. AI may write quote-backed risks (e.g., prospect states the CFO is NetSuite-biased); pattern-inferred risks without quotes belong in deal_hypotheses, not here.", "signals": "the CFO prefers; we''ve been burned by; no budget approved yet; timeline depends on"}'::jsonb, '["Quote: ''Our CFO came from a NetSuite shop and loves it'' -> risk: competitive bias at economic buyer", "severity high", "quote-backed."]'::jsonb, '["AI pattern: ''no exec sponsor identified yet'' with no quote -> deal_hypotheses, not deal_risks."]'::jsonb, true),
('contact_role_fact', 'platform', NULL, NULL, 'Role-in-deal facts about a person: champion/EB/signer status, influence, alignment, sentiment, reporting line. Identity facts (name, title) may come from research with citation; ROLE facts require call evidence.', '["NOT role facts: title-based inference (CFO does not equal economic buyer without evidence: that inference is a deal_hypotheses row), Apollo seniority labels as influence claims."]'::jsonb, '{"row_rules": "Match-before-insert on name/email (Apollo rows enrich, never duplicate). is_champion/is_economic_buyer/is_signer set only on quote-backed evidence; otherwise hypothesis territory.", "signals": "I report to; the decision is mine; I''ll champion this internally; final sign-off is"}'::jsonb, '["Quote: ''Whatever we pick, Senake signs it'' -> Senake: is_signer=true, quote-backed."]'::jsonb, '["Apollo: ''Senake Gajamera, CFO'' -> identity fact (cited)", "does NOT set is_economic_buyer."]'::jsonb, true),
('deal_module', 'platform', NULL, NULL, 'An SC-managed record that a Sage Intacct module is recommended for this deal and/or was demonstrated. Recommendations may be AI-SUGGESTED from verified discovery facts but only become recommended on SC/AE confirmation.', '["AI never sets is_recommended directly", "suggestions only. Demo detection proposes, SC confirms."]'::jsonb, '{"row_rules": "One row per module per deal; is_recommended / is_demoed independently togglable; demoed links the demo conversation; recommended_reason references the driving discovery facts; maps to pricebook SKUs via the module reference list.", "signals": "n/a (human/AI-suggest surface, not transcript-extracted; demo detection may set is_demoed candidates from demo-call transcripts for confirmation)"}'::jsonb, '["inventory_type=buy_to_sell + warehouse_count=4 -> AI suggests Inventory + Order Entry modules", "SC confirms -> is_recommended."]'::jsonb, '["AI auto-marking modules recommended without confirmation -> forbidden."]'::jsonb, true)
